import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CmPiTyN0.js";const u=JSON.parse('{"title":"Vehicle-Deployed UAVs","description":"","frontmatter":{"title":"Vehicle-Deployed UAVs","outline":"deep"},"headers":[],"relativePath":"en/wiki/uav.md","filePath":"en/wiki/uav.md","lastUpdated":1794811249000}'),r={name:"en/wiki/uav.md"};function n(d,e,o,c,h,p){return t(),l("div",null,[...e[0]||(e[0]=[i('<p><a href="./../index.html">← Back to Wiki Home</a></p><h2 id="_8-vehicle-deployed-uavs-and-support-vehicles" tabindex="-1">8. Vehicle-Deployed UAVs and Support Vehicles <a class="header-anchor" href="#_8-vehicle-deployed-uavs-and-support-vehicles" aria-label="Permalink to &quot;8. Vehicle-Deployed UAVs and Support Vehicles&quot;">​</a></h2><h3 id="_8-1-deployable-support-vehicles" tabindex="-1">8.1 Deployable Support Vehicles <a class="header-anchor" href="#_8-1-deployable-support-vehicles" aria-label="Permalink to &quot;8.1 Deployable Support Vehicles&quot;">​</a></h3><p>Some RVP vehicles can deploy support vehicles and switch control between the parent vehicle and the deployed vehicle.</p><table tabindex="0"><thead><tr><th>Type</th><th>Examples</th></tr></thead><tbody><tr><td>Reconnaissance UAV</td><td>SUAV light reconnaissance UAV, quadcopter reconnaissance UAV</td></tr><tr><td>Attack UAV</td><td>Quadcopter bombing UAV (drops PG-7V), quadcopter suicide UAV</td></tr><tr><td>Unmanned ground vehicle</td><td>RAWR unmanned combat vehicle</td></tr><tr><td>Radar relay vehicle</td><td>Buk-M3&#39;s 96L6 radar vehicle</td></tr></tbody></table><p>Parent vehicles: LAV-25, ZBL-08A, ZTZ100, and M142 can deploy the SUAV or quadcopter UAV; LAV-25, ZBL-08A, and ZTZ100 can also deploy RAWR; Buk-M3 deploys the 96L6 radar vehicle.</p><p>Gameplay example: an M142 launches a reconnaissance UAV, which marks enemy vehicles with its reconnaissance pod; the M142 then fires rockets directly at the enemy markers on the tactical map.</p><p>Deployment and control:</p><ul><li>Supports deployment, control switching, and automatic UAV circling.</li><li>Support vehicles are limited by signal range and automatically recovered when out of range.</li><li>Redeployment has a cooldown.</li><li>While a support vehicle is deployed, the parent vehicle&#39;s seats are locked.</li></ul><h3 id="_8-2-buk-m3-radar-vehicle-and-launcher" tabindex="-1">8.2 Buk-M3: Radar Vehicle and Launcher <a class="header-anchor" href="#_8-2-buk-m3-radar-vehicle-and-launcher" aria-label="Permalink to &quot;8.2 Buk-M3: Radar Vehicle and Launcher&quot;">​</a></h3><p>Buk-M3 can deploy one 96L6 radar vehicle:</p><ul><li>After deployment, control can be switched and the two vehicles can be positioned separately.</li><li>The radar vehicle provides target information and the launcher fires; the two vehicles are linked by datalink.</li><li>The radar vehicle can serve as a radar relay.</li></ul><h3 id="_8-3-shipboard-helicopter-landing" tabindex="-1">8.3 Shipboard Helicopter Landing <a class="header-anchor" href="#_8-3-shipboard-helicopter-landing" aria-label="Permalink to &quot;8.3 Shipboard Helicopter Landing&quot;">​</a></h3><ul><li>This is an experimental feature, recommended mainly for filming.</li><li>Only the 052D currently has a helicopter landing pad.</li><li>When a helicopter approaches the ship, press <code>P</code> to start automatic landing.</li></ul><hr>',15)])])}const m=a(r,[["render",n]]);export{u as __pageData,m as default};
